FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 016: sheet metal relief study: bend reliefs and corner reliefs. Generated by tools/fixtures/gen-batch-016.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function pointAtFraction(context is Context, part is Query, fx is number, fy is number, fz is number) returns Vector
{
    const b = evBox3d(context, { "topology" : part, "tight" : true });
    return vector(b.minCorner[0] + fx * (b.maxCorner[0] - b.minCorner[0]),
                  b.minCorner[1] + fy * (b.maxCorner[1] - b.minCorner[1]),
                  b.minCorner[2] + fz * (b.maxCorner[2] - b.minCorner[2]));
}

function atFraction(context is Context, part is Query, entityType is EntityType, fx is number, fy is number, fz is number) returns Query
{
    return qContainsPoint(qOwnedByBody(part, entityType), pointAtFraction(context, part, fx, fy, fz));
}

// bend-relief: obround, 1 mm thick, 1 mm radius
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 1 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"), "tangentPropagation" : false, "bends" : qNothing() });
    sheetMetalFlange(context, id + "flange1", { "edges" : atFraction(context, qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.EDGE, 1, 0.5, 1), "flangeAlignment" : SMFlangeAlignment.INNER, "limitType" : SMFlangeBoundingType.BLIND, "distance" : 15 * millimeter, "angleControlType" : SMFlangeAngleControlType.BEND_ANGLE, "oppositeDirection" : false, "bendAngle" : 90 * degree, "autoMiter" : true, "useDefaultRadius" : true, "isPartialFlange" : true, "chainType" : SMPartialFlangeChainType.PER_EDGE, "flipFlangeBounds" : false, "holdAdjacentEdges" : false, "firstBoundType" : SMFlangeBoundingType.BLIND, "firstBoundOffset" : 5 * millimeter, "hasSecondBound" : true, "secondBoundType" : SMFlangeBoundingType.BLIND, "secondBoundOffset" : 5 * millimeter });
}

